var boyz = GameState.get_unit("U_BOYZ_K")
var k = 0
for m in boyz["models"]:
	if str(m.get("id", "")) == "m1":
		continue
	m["position"] = {"x": 1100.0 + (k % 3) * 60.0, "y": 1100.0 + floor(k / 3.0) * 60.0}
	m["alive"] = true
	k += 1
for m in boyz["models"]:
	if str(m.get("id", "")) == "m1":
		m["position"] = {"x": 1420.0, "y": 1160.0}
		m["alive"] = true
GameState.get_unit("U_WEIRDBOY_J")["models"][0]["position"] = {"x": 1330.0, "y": 1160.0}
return "%s/%s" % [str(GameState.get_unit("U_WEIRDBOY_J").get("attached_to", "")), str(k)]

var solo = AttackSequence.check_unit_coherency(GameState.get_unit("U_BOYZ_K"))
var grp = AttackSequence.check_attached_unit_coherency("U_BOYZ_K", GameState.state["units"])
return "solo=%s grp=%s" % [str(solo.offenders), str(grp.coherent)]

for m in GameState.get_unit("U_BOYZ_K")["models"]:
	if str(m.get("id", "")) == "m1":
		m["position"] = {"x": 1490.0, "y": 1160.0}
var coh = AttackSequence.check_attached_unit_coherency("U_BOYZ_K", GameState.state["units"])
return "%s|%s" % [str(coh.coherent), str(coh.offenders)]

var mk = tree.root.get_node("Main/BoardRoot/TokenLayer/CoherencyWarning_U_BOYZ_K_m1")
# 32mm base radius (25.2px) + 2" coherency reach (80px)
return abs(mk.reach_radius_px - 105.2) < 0.05
